fn check_min_heap(arr: [int]) -> bool:
    """
    Write a function to check if the given array represents min heap or not.
    """
    n = len(arr)
    for i in range(n // 2):
        left_child_index = 2 * i + 1
        right_child_index = 2 * i + 2

        # Check left child (always exists since i < n // 2)
        if arr[i] > arr[left_child_index]:
            return False

        # Check right child if it exists
        if right_child_index < n:
            if arr[i] > arr[right_child_index]:
                return False

    return True

